31	// item ids are not seed-controlled). Descriptions in each test are chosen distinct — none a substring
32	// of another — so this is unambiguous. Mirrors how project-invoices.spec.ts finds a freshly added row
33	// by the value it shows.
34	const rowByDescription = (page: Page, description: string): Locator =>
35	  lineItemRows(page).filter({
36	    has: page.getByTestId('lineitem-description').getByText(description, { exact: true }),
37	  });
38	
39	// The invoice's worked-out total lives on its detail page. Scope to the detail page so the match is
40	// the invoice total and not something else named the same elsewhere.
41	const invoiceTotal = (page: Page): Locator =>
42	  page.getByTestId('invoice-detail-page').getByTestId('invoice-amount');
43	
44	// A quantity is a bare count; a price, a line amount or the total may be rendered as money ($300.00)
45	// or bare (300). Assert the figure it carries is PRESENT, so the test binds to the value and not to
46	// one presentation. Figures in each test are chosen so no value is a substring of another.
47	async function expectValue(cell: Locator, n: number): Promise<void> {
48	  await expect(cell).toContainText(String(n));
49	}
