            { description: 'Fixed hosting', qty: 1, unitPrice: 40 }, //             40
          ],
        },
      ],
    });

    await gotoInvoice(page, 1);
    await expect(lineItemRows(page)).toHaveCount(2);
    await expectValue(invoiceTotal(page), 240); // 200 + 40

    // The consulting line was charged at the wrong rate — remove it.
    await removeControl(rowByDescription(page, 'Consulting at wrong rate')).click();
    await expect(rowByDescription(page, 'Consulting at wrong rate')).toHaveCount(0);
    await expect(lineItemRows(page)).toHaveCount(1);
    await expectValue(invoiceTotal(page), 40); // hosting only

    // Add the corrected line in its place: 2 × 150 = 300.
    await page.getByTestId('lineitem-form-description').fill('Consulting at correct rate');
    await page.getByTestId('lineitem-form-qty').fill('2');
    await page.getByTestId('lineitem-form-unitprice').fill('150');
    await page.getByTestId('lineitem-form-submit').click();

    const corrected = rowByDescription(page, 'Consulting at correct rate');
    await expect(corrected).toHaveCount(1);
    await expectValue(corrected.getByTestId('lineitem-amount'), 300);
    await expect(lineItemRows(page)).toHaveCount(2);

    // The total reflects the change: 40 + 300 = 340, and it all survives a fresh load.
    await expectValue(invoiceTotal(page), 340);
    await page.reload();
    await expect(page.getByTestId('invoice-detail-page')).toBeVisible();
    await expect(lineItemRows(page)).toHaveCount(2);
    await expect(rowByDescription(page, 'Consulting at wrong rate')).toHaveCount(0);
    await expect(rowByDescription(page, 'Consulting at correct rate')).toHaveCount(1);
    await expectValue(invoiceTotal(page), 340);
  });
});

